suppressPackageStartupMessages({library(data.table);library(ggplot2);library(scales);library(grid)})
root<-normalizePath(getwd());O<-file.path(root,'细胞定位/SYN01_Entrez_downstream_20261001')
# Original standalone_figures_20260904 theme, geometry, marks and palettes.
pal<-c(lung='#137C8B',brain='#4B67A1',control='#6F7782',copd='#C4573E',ne='#5987A8',e='#D38235',dark='#22262A')
th<-function()theme_classic(base_size=10,base_family='Arial')+theme(axis.line=element_line(linewidth=.35,colour=pal[['dark']]),axis.ticks=element_line(linewidth=.35,colour=pal[['dark']]),text=element_text(size=10),axis.title=element_text(size=10),axis.text=element_text(size=10),legend.title=element_text(size=10,face='bold'),legend.text=element_text(size=10),plot.title=element_text(size=10,face='bold',margin=margin(b=3)),plot.subtitle=element_text(size=10,lineheight=1.08,margin=margin(b=6)),plot.caption=element_text(size=10,hjust=0,margin=margin(t=5)),plot.title.position='plot',plot.caption.position='plot',panel.grid=element_blank(),plot.margin=margin(8,10,8,8))
fp<-function(x)ifelse(x<.001,formatC(x,format='e',digits=2),sprintf('%.3f',x))
savep<-function(p,id,d,w,h){fwrite(d,file.path(O,'source_data',paste0(id,'.tsv')),sep='\t');quartz(type='pdf',file=file.path(O,'figures',paste0(id,'.pdf')),width=w/25.4,height=h/25.4,family='Arial',pointsize=10,bg='white');print(p);dev.off();fwrite(data.table(width_mm=w,height_mm=h,Arial_pt=10),file.path(O,'qa',paste0(id,'_geometry.tsv')),sep='\t')}
x<-fread(file.path(O,'results/lung/tables/axisA_donor_broad_medians.tsv'));test<-fread(file.path(O,'results/lung/tables/axisA_donor_COPD_vs_control.tsv'))[broad_celltype=='Myeloid']
d<-x[eligible==TRUE & broad_celltype=='Myeloid'];d[,disease_group:=factor(disease_group,levels=c('Control','COPD'))]
set.seed(20260904)
p<-ggplot(d,aes(disease_group,median_axisA_ucell,colour=disease_group,fill=disease_group))+geom_violin(width=.78,alpha=.14,linewidth=.45,trim=FALSE)+geom_boxplot(width=.34,outlier.shape=NA,alpha=.42,linewidth=.45)+geom_jitter(width=.10,height=0,size=1.25,alpha=.78)+scale_colour_manual(values=pal[c('control','copd')] |> setNames(c('Control','COPD')),guide='none')+scale_fill_manual(values=pal[c('control','copd')] |> setNames(c('Control','COPD')),guide='none')+scale_x_discrete(labels=c(Control=paste0('Control\n(n = ',test$n_group1,')'),COPD=paste0('COPD\n(n = ',test$n_group2,')')))+labs(title='Lung myeloid: COPD versus control',subtitle=paste0('Donor-level Wilcoxon P = ',fp(test$wilcoxon_p),'\nBH FDR across six broad types = ',fp(test$wilcoxon_fdr_bh)),x=NULL,y='Axis A UCell score',caption='Boxes: median and interquartile range.\nEach point represents one donor.')+th()
savep(p,'Disease_Lung_myeloid_COPD_control',d,110,92)
b<-fread(file.path(O,'results/disease/brain_CPS_local_association.tsv'));d<-fread(file.path(O,'results/disease/brain_CPS_donor_data.tsv'))[Supertype=='Micro-PVM_2'];d[,study_display:=fifelse(study=='ACT','ACT','ADRC')];test<-b[Supertype=='Micro-PVM_2']
p<-ggplot(d,aes(cps_local,AxisA_full_measured_UCell,colour=study_display))+geom_smooth(aes(group=1),method='lm',formula=y~x,se=TRUE,colour='#A6AFBA',fill='#E5E8EC',linewidth=.7)+geom_point(size=1.6,alpha=.82)+scale_colour_manual(values=c(ACT='#4B67A1',ADRC='#B3724A'))+labs(title='Micro-PVM_2: DFC pathology burden',subtitle=paste0('Raw donor relation; adjusted model\nBH FDR = ',fp(test$BH_FDR_across_eligible_supertypes)),x='DFC CPS_Local',y='Axis A UCell score',colour='Study',caption='Points are donors; fitted line is descriptive.\nInference uses the adjusted HC3 model.')+th()+theme(legend.position='right')
savep(p,'Disease_Brain_MicroPVM2_CPS_scatter',d,135,95)
b[,annotation:=factor(Supertype,levels=rev(c('Micro-PVM_2','Micro-PVM_2_3-SEAAD','Micro-PVM_3-SEAAD')))]
p<-ggplot(b,aes(beta_UCell_per_1SD_CPS_Local,annotation))+geom_vline(xintercept=0,colour='#858C94',linewidth=.5,linetype='22')+geom_errorbar(aes(xmin=ci95_low,xmax=ci95_high),orientation='y',width=0,linewidth=.85,colour='#AEB9D1')+geom_point(size=3,colour=pal[['brain']])+scale_x_continuous(labels=label_number(accuracy=.001),expand=expansion(mult=c(.1,.1)))+labs(title='Adjusted SEA-AD pathology association',subtitle='All three eligible supertypes; HC3 95% CI',x='UCell change per 1-SD higher CPS_Local',y=NULL,caption='Adjusted for age, sex, PMI, RIN and study.\nBH FDR is reported for all three models in the source table.')+th()
savep(p,'Disease_Brain_CPS_all_three_adjusted_effects',b,155,75)
primary<-b[Supertype=='Micro-PVM_2'];pp<-p %+% primary;pp<-pp+labs(subtitle=paste0('HC3 95% CI; BH FDR = ',fp(primary$BH_FDR_across_eligible_supertypes)));savep(pp,'Disease_Brain_MicroPVM2_adjusted_effect',primary,155,65)
for(endpoint in c('COPD_vs_control','E_vs_NE_COPD')){
 d<-fread(file.path(O,'results/lung/tables',paste0('axisA_donor_',endpoint,'.tsv')));setorder(d,delta_group2_minus_group1);d[,annotation:=factor(broad_celltype,levels=broad_celltype)]
 labs<-c(unique(d$group1),unique(d$group2));co<-if(endpoint=='COPD_vs_control')c(pal[['control']],pal[['copd']]) else c(pal[['ne']],pal[['e']])
 p<-ggplot(d,aes(y=annotation))+geom_segment(aes(x=median_group1,xend=median_group2,yend=annotation),linewidth=.7,colour='#C9CED3')+geom_point(aes(x=median_group1,colour=labs[1]),size=2.3)+geom_point(aes(x=median_group2,colour=labs[2]),size=2.3)+scale_colour_manual(values=setNames(co,labs),breaks=labs,name=NULL)+scale_x_continuous(labels=label_number(accuracy=.01),expand=expansion(mult=c(.03,.08)))+labs(title=paste0('Lung: ',gsub('_',' ',endpoint)),subtitle='Donor-level Wilcoxon tests; six-type BH',x='Median donor Axis A UCell score',y=NULL,caption='Points show group medians.\nAll six types are reported in the source table.')+th()+theme(legend.position='top')
 savep(p,paste0('Disease_Lung_all_broad_',endpoint),d,135,94)
}
writeLines(capture.output(sessionInfo()),file.path(O,'provenance/disease_figure_sessionInfo.txt'))
